import {poseWorldJoints} from './studio-poses.mjs';
import {studioLightColor} from './studio-planner.mjs';

export function sphereLabels(language='EN'){
 const i=Math.max(0,['EN','HU','DE','FR','ES','IT','PT','PL'].indexOf(language));const w={
 title:'Light sphere|Fénygömb|Lichtkugel|Sphère lumineuse|Esfera de luz|Sfera luminosa|Esfera de luz|Kula światła',enabled:'Use light sphere|Fénygömb használata|Lichtkugel nutzen|Utiliser la sphère|Usar esfera|Usa sfera|Usar esfera|Użyj kuli',follow:'Follow the visible figures|Látható figurák követése|Sichtbaren Figuren folgen|Suivre les figures visibles|Seguir figuras visibles|Segui figure visibili|Seguir figuras visíveis|Śledź widoczne postacie',edit:'Place / move the sphere|Gömb elhelyezése / mozgatása|Kugel platzieren / bewegen|Placer / déplacer la sphère|Colocar / mover esfera|Posiziona / sposta sfera|Colocar / mover esfera|Umieść / przesuń kulę',suggest:'Suggested sphere|Javasolt fénygömb|Kugel vorschlagen|Sphère suggérée|Esfera sugerida|Sfera suggerita|Esfera sugerida|Sugerowana kula',radius:'Radius (m)|Sugár (m)|Radius (m)|Rayon (m)|Radio (m)|Raggio (m)|Raio (m)|Promień (m)',strength:'Descriptive strength|Leíró fényerő|Beschreibende Stärke|Intensité descriptive|Intensidad descriptiva|Intensità descrittiva|Intensidade descritiva|Siła opisowa',softness:'Softness / surrounding fill|Lágyság / környezeti derítés|Weichheit / Umgebungslicht|Douceur / remplissage|Suavidad / relleno|Morbidezza / riempimento|Suavidade / preenchimento|Miękkość / wypełnienie',kelvin:'Colour temperature (K)|Színhőmérséklet (K)|Farbtemperatur (K)|Température (K)|Temperatura (K)|Temperatura (K)|Temperatura (K)|Temperatura (K)',color:'Tint|Fény színe|Farbton|Teinte|Tinte|Tinta|Tom|Odcień',colorMode:'Colour control|Színvezérlés|Farbsteuerung|Réglage couleur|Control de color|Controllo colore|Controlo de cor|Sterowanie kolorem',temperature:'Temperature|Színhőmérséklet|Temperatur|Température|Temperatura|Temperatura|Temperatura|Temperatura',gel:'Custom colour|Egyedi szín|Eigene Farbe|Couleur personnalisée|Color propio|Colore personalizzato|Cor própria|Własny kolor',azimuth:'Main light direction (°)|Főfény iránya (°)|Hauptlichtrichtung (°)|Direction principale (°)|Dirección principal (°)|Direzione principale (°)|Direção principal (°)|Kierunek światła (°)',elevation:'Main light height angle (°)|Főfény emelési szöge (°)|Lichthöhenwinkel (°)|Élévation lumière (°)|Elevación luz (°)|Elevazione luce (°)|Elevação luz (°)|Kąt wysokości światła (°)',x:'Position left / right (m)|Helyzet balra / jobbra (m)|Position links / rechts (m)|Position gauche / droite (m)|Posición izquierda / derecha (m)|Posizione sinistra / destra (m)|Posição esquerda / direita (m)|Pozycja lewo / prawo (m)',y:'Position height (m)|Elhelyezési magasság (m)|Positionshöhe (m)|Hauteur de position (m)|Altura de posición (m)|Altezza posizione (m)|Altura da posição (m)|Wysokość pozycji (m)',
 wheel:'3D view: wheel = orbit · Shift + wheel = tilt · Ctrl + wheel = zoom.|Térbeli nézet: görgő = körbeforgatás · Shift + görgő = billentés · Ctrl + görgő = nagyítás.|3D: Rad = kreisen · Umschalt+Rad = neigen · Strg+Rad = zoomen.|Vue 3D : molette = tourner · Maj = incliner · Ctrl = zoom.|Vista 3D: rueda = girar · Mayús = inclinar · Ctrl = zoom.|Vista 3D: rotella = ruota · Maiusc = inclina · Ctrl = zoom.|Vista 3D: roda = rodar · Shift = inclinar · Ctrl = zoom.|Widok 3D: kółko = obrót · Shift = nachylenie · Ctrl = zoom.',
 help:'Enable body preview to see the schematic light. Suggested sphere frames the visible figures. Move mode: click or drag in the scene; X/Y move, depth stays fixed. Near an edge-on view, rotate or use the number fields. The sphere is omitted from exports and described as an invisible lighting guide in the prompt. This is an approximate preview, not physical relighting or a guarantee of generator output.|A sematikus fény a testmodell előnézetén látszik. A Javasolt fénygömb körbeveszi a látható figurákat. Mozgatás: kattints vagy húzz a térben; X/Y mozdul, a mélység megmarad. Élirányú nézetnél fordíts a téren vagy használd a számmezőket. A gömb nem kerül az exportképre, a prompt láthatatlan fényvezetőként írja le. Közelítő támpont, nem fizikai újravilágítás vagy garantált generálási eredmény.|Körpervorschau zeigt das schematische Licht. Vorschlag umfasst Figuren. Klick/Ziehen bewegt X/Y, Tiefe bleibt. Bei Kantenansicht drehen oder Zahlen nutzen. Kugel nicht exportiert; unsichtbare Lichtanweisung im Prompt. Näherung, keine physikalische Simulation.|Aperçu du corps : lumière schématique. Suggestion englobe les figures. Clic/glisser déplace X/Y, profondeur fixe. Tournez ou utilisez les nombres si vue de côté. Sphère hors export, guide invisible dans le prompt. Aperçu approximatif, sans garantie.|Vista del cuerpo muestra luz esquemática. Sugerencia engloba figuras. Clic/arrastre mueve X/Y, profundidad fija. Gira o usa números en vista de canto. Esfera fuera de exportación, guía invisible en prompt. Vista aproximada, sin garantía.|Anteprima corpo mostra luce schematica. Suggerimento racchiude figure. Clic/trascina muove X/Y, profondità fissa. Ruota o usa numeri di taglio. Sfera esclusa dall’export, guida invisibile nel prompt. Anteprima approssimata, senza garanzia.|Prévia do corpo mostra luz esquemática. Sugestão envolve figuras. Clique/arraste move X/Y, profundidade fixa. Rode ou use números de lado. Esfera não exportada, guia invisível no prompt. Prévia aproximada, sem garantia.|Podgląd bryły pokazuje schemat światła. Propozycja obejmuje postacie. Kliknij/przeciągnij X/Y, głębia stała. Przy widoku krawędziowym obróć lub użyj liczb. Kula poza eksportem, niewidoczna wskazówka w prompcie. Przybliżenie, bez gwarancji.',
 limited:'Rotate the view slightly or use X / height fields; depth was kept.|Fordíts kissé a nézeten, vagy használd az X / magasság mezőt; a mélység megmaradt.|Ansicht drehen oder X/Höhe nutzen; Tiefe bleibt.|Tournez la vue ou utilisez X/hauteur ; profondeur conservée.|Gira vista o usa X/altura; profundidad conservada.|Ruota vista o usa X/altezza; profondità conservata.|Rode vista ou use X/altura; profundidade mantida.|Obróć widok lub użyj X/wysokości; głębia zachowana.'};return Object.fromEntries(Object.entries(w).map(([k,v])=>[k,v.split('|')[i]]));
}

export function attachLightSphere({host,getPlan,apply,getLanguage,getView,rotate,redraw,shape,svg,pointer,isLocked,onEnable}){
 const D=document,t=()=>sphereLabels(getLanguage()),el=tag=>D.createElement(tag),root=el('details'),heading=el('summary'),fields={},words=[];let edit=false,drag=null,preview=null;
 root.id='virtual-studio-light-sphere';root.className='pose-sphere';root.append(heading);host.append(root);const status=el('p');status.setAttribute('role','status');status.className='sphere-status';
 function field(key,type,min,max,step){const l=el('label'),span=el('span'),n=el(type==='select'?'select':'input');if(type!=='select')n.type=type;n.dataset.sphereField=key;if(min!==undefined){n.min=min;n.max=max;n.step=step;}l.append(span,n);words.push([span,key]);fields[key]=n;root.append(l);n.addEventListener('change',()=>{if(isLocked()){refresh();return;}if(type==='number'&&(n.value===''||!Number.isFinite(Number(n.value)))){refresh();return;}if(key==='edit'){edit=n.checked;redraw();return;}const p=getPlan(),s=normalizeLightSphere(p.lightSphere),v=type==='checkbox'?n.checked:type==='number'?Number(n.value):n.value;if(key==='x'||key==='y'){s.position=sphereCenter(p,poseWorldJoints);s.position[key]=v;s.follow=false;}else {if(key==='follow'&&!v)s.position=sphereCenter(p,poseWorldJoints);s[key]=v;}p.lightSphere=normalizeLightSphere(s);if(apply(p)&&key==='enabled'&&v)onEnable();});return n;}
 field('enabled','checkbox');field('follow','checkbox');field('edit','checkbox');const suggest=el('button');suggest.type='button';suggest.dataset.sphereAction='suggest';suggest.addEventListener('click',()=>{if(isLocked())return;const p=getPlan();p.lightSphere=recommendedSphere(p,poseWorldJoints);edit=true;if(apply(p))onEnable();});root.append(suggest);
 for(const [key,a,b,step]of [['x',-5,5,.01],['y',0,6,.01],['radius',.2,5,.01],['strength',0,100,1],['softness',0,100,1],['kelvin',2000,10000,100],['azimuth',-180,180,1],['elevation',-85,85,1]])field(key,'number',a,b,step);
 field('colorMode','select');field('color','color');const wheelHelp=el('p');wheelHelp.className='vs-help';const help=el('details'),helpSummary=el('summary'),helpText=el('p');helpText.className='vs-help';help.append(helpSummary,helpText);root.append(wheelHelp,help,status);
 function refresh(){heading.textContent=t().title;suggest.textContent=t().suggest;suggest.title=t().help;wheelHelp.textContent=t().wheel;helpSummary.textContent=t().title+' — ?';helpText.textContent=t().help;for(const [n,key]of words)n.textContent=t()[key];const p=preview||getPlan(),s=normalizeLightSphere(p.lightSphere),center=sphereCenter(p,poseWorldJoints);for(const [key,n]of Object.entries(fields)){n.setAttribute('aria-label',t()[key]);n.title=key==='edit'?t().help:t()[key];n.disabled=isLocked();if(n.type==='checkbox')n.checked=key==='edit'?edit:s[key];else if(n.tagName==='SELECT'){n.replaceChildren(...['temperature','gel'].map(v=>new Option(t()[v],v)));n.value=s.colorMode;}else n.value=String(key==='x'||key==='y'?Number(center[key].toFixed(4)):s[key]);}fields.edit.disabled=isLocked()||!s.enabled;fields.kelvin.parentElement.hidden=s.colorMode!=='temperature';fields.color.parentElement.hidden=s.colorMode!=='gel';suggest.disabled=isLocked();}
 function begin(e,atCenter=false){const ctx=getView(),p=getPlan();if(!edit||!p.lightSphere.enabled||isLocked()||ctx.view==='camera'||e.button&&e.button!==0)return false;const point=pointer(e);if(!point)return false;e.preventDefault();e.stopPropagation?.();const center=sphereCenter(p,poseWorldJoints),screen=ctx.tr.project(center);drag={before:p,center,start:atCenter?point:screen,tr:ctx.tr,pointerId:e.pointerId};svg.setPointerCapture?.(e.pointerId);move(e);return true;}
 function down(e){if(drag)return true;if(e.target&&e.target!==svg&&!e.target.dataset?.poseBackground)return false;return begin(e);}
 function move(e){if(!drag)return false;if(e.pointerId!=null&&drag.pointerId!=null&&e.pointerId!==drag.pointerId)return true;const p=pointer(e);if(!p)return true;const next=spherePlaneMove(drag.center,drag.tr.basis,(p.x-drag.start.x)*(e.shiftKey?.1:1),(p.y-drag.start.y)*(e.shiftKey?.1:1),drag.tr.scale);if(!next){status.textContent=t().limited;return true;}preview=JSON.parse(JSON.stringify(drag.before));preview.lightSphere={...preview.lightSphere,follow:false,position:next};status.textContent='';redraw();return true;}
 function end(cancel=false){if(!drag)return false;const own=drag,next=preview;drag=null;preview=null;if(own.pointerId!=null&&svg.hasPointerCapture?.(own.pointerId))svg.releasePointerCapture?.(own.pointerId);if(next&&!cancel)apply(next);else redraw();refresh();return true;}
 function draw(tr,handles=false){const p=preview||getPlan(),s=normalizeLightSphere(p.lightSphere);if(!s.enabled||!tr)return;const center=sphereCenter(p,poseWorldJoints),color=studioLightColor(s);if(!handles){for(const plane of ['xy','xz','yz']){const pts=[];for(let i=0;i<=64;i++){const a=i/64*Math.PI*2,q={...center};q[plane[0]]+=Math.cos(a)*s.radius;q[plane[1]]+=Math.sin(a)*s.radius;const point=tr.project(q);pts.push(point.x+','+point.y);}svg.append(shape('polyline',{points:pts.join(' '),fill:'none',stroke:color,'stroke-opacity':.35,'stroke-width':1.5,'pointer-events':'none','data-sphere-guide':plane}));}return;}if(!edit)return;const q=tr.project(center),g=shape('g',{'data-sphere-handle':'center',style:'cursor:move'});g.append(shape('circle',{cx:q.x,cy:q.y,r:16,fill:'#10212b',stroke:color,'stroke-width':3}),shape('text',{x:q.x,y:q.y+5,'text-anchor':'middle',fill:color,'font-size':15,'pointer-events':'none'},'✥'));g.addEventListener('pointerdown',e=>begin(e,true));svg.append(g);}
 function wheel(e){if(drag||!getPlan().lightSphere.enabled||getView().view!=='space'||e.ctrlKey||e.metaKey||!Number.isFinite(e.deltaY))return false;e.preventDefault();if(e.deltaY)rotate(Math.sign(e.deltaY)*(e.shiftKey?0:5),Math.sign(e.deltaY)*(e.shiftKey?2:0));return true;}
 return {refresh,draw,pointerDown:down,pointerMove:move,endDrag:end,wheel,getPreview:()=>preview,dragTransform:()=>drag?.tr,isDragging:()=>!!drag,escape(){if(end(true))return true;if(edit){edit=false;refresh();redraw();return true;}return false;},open(){root.open=true;root.scrollIntoView({block:'start'});},root};
}
